definition.script:
node {
  timestamps {
    stage('Checkout') {
      deleteDir()
      sh '''#!/bin/sh
        set -eu
        git clone --depth 1 --single-branch --branch main https://github.com/kyoungrae/IfileManager.git source
        test -f source/Jenkinsfile
        test -f source/docker-compose.yml
        git -C source rev-parse --verify HEAD
      '''
    }
    dir('source') {
      def runPipeline = load 'Jenkinsfile'
      runPipeline()
    }
  }
}
